def fingerprint_and_retire_duplicates(apps, schema_editor):
    """Fill fingerprints, then retire extra copies that would break the new unique rules.

    Within one paper (global PYQs) or one institute bank, the published copy is kept (else the
    oldest); the others become "retired" so attempts and history that point at them still work.
    """
    from collections import defaultdict
    from apps.content.fingerprint import question_fingerprint
    Question = apps.get_model("content", "Question")
    rows = list(Question.objects.only("id", "stem", "options", "figure_paths", "paper_id", "tenant_id", "status"))
    for q in rows:
        q.fingerprint = question_fingerprint(q.stem, q.options, q.figure_paths)
    groups = defaultdict(list)
    for q in rows:
        if not q.fingerprint or q.status == "retired":
            continue
        if q.paper_id:
            groups[("paper", q.paper_id, q.fingerprint)].append(q)
        if q.tenant_id:
            groups[("tenant", q.tenant_id, q.fingerprint)].append(q)
    retired = set()
    for copies in groups.values():
        copies = [q for q in copies if q.pk not in retired]
        if len(copies) < 2:
            continue
        keep = min(copies, key=lambda q: (q.status != "published", q.pk))
        retired.update(q.pk for q in copies if q.pk != keep.pk)
    # Retire first, then store fingerprints, so this is safe even where the unique rules already exist.
    if retired:
        Question.objects.filter(pk__in=retired).update(status="retired")
        print(f"\n  Retired {len(retired)} duplicate question(s): {sorted(retired)}")
    Question.objects.bulk_update(rows, ["fingerprint"], batch_size=500)


